%[text] # example for calculating solar radiation pressure (SRP)
clc
clear
close all
%[text] ## parameters
const = orbitConst; % constant parameters for orbit
%%
%[text] ## read object
sat = readSC('boxWing.obj') %[output:14704acc] %[output:432111bb]

% check satellite shape
showSC(sat) %[output:9545d00b]
%[text] ## set illumination condition
d = au2km(1.0,const) * 10^3; % distance between satellite and Sun, m
sunB = [0 0 1]; % sun direction from satellite expressed with body-fixed frame
%[text] ## calculation
sat = srpSimple(sat, sunB, d, const) %[output:82442833]
sat = srpAS(sat, sunB, d, const) %[output:303588e3]
sat = srpCT(sat, sunB, d, const) %[output:6d1fb0f1]

sat.force % SRP forces at each facet, N, nx3 matrix %[output:243f25a2]
sat.torque % SRP torques at each facet, Nm, nx3 matrix %[output:1189d0d0]

sum(sat.force,1) % total SRP force expressed with body-fixed frame %[output:032cdfbb]
sum(sat.torque,1) % total SRP force expressed with body-fixed frame %[output:563fa376]

